  1	// RUN: %dafny /compile:3 /spillTargetCode:2 /compileTarget:cs "%s" > "%t"
  2	// RUN: %dafny /compile:3 /spillTargetCode:2 /compileTarget:js "%s" >> "%t"
  3	// RUN: %dafny /compile:3 /spillTargetCode:2 /compileTarget:go "%s" >> "%t"
  4	// RUN: %dafny /compile:3 /spillTargetCode:2 /compileTarget:java "%s" >> "%t"
  5	// RUN: %diff "%s.expect" "%t"
  6	
  7	method LinearSearch(a: array<int>, key: int) returns (n: nat)
  8	  ensures 0 <= n <= a.Length
  9	  ensures n == a.Length || a[n] == key
 10	{
 11	  n := 0;
 12	  while n < a.Length
 13	    invariant n <= a.Length
 14	  {
 15	    if a[n] == key {
 16	      return;
 17	    }
 18	    n := n + 1;
 19	  }
 20	}
 21	
 22	method PrintArray<A>(a: array?<A>) {
 23	  if (a == null) {
 24	    print "It's null\n";
 25	  } else {
 26	    var i := 0;
 27	    while i < a.Length {
 28	      print a[i], " ";
 29	      i := i + 1;
 30	    }
 31	    print "\n";
 32	  }
 33	}
 34	
 35	method Main() {
 36	  var a := new int[23];
 37	  var i := 0;
 38	  while i < 23 {
 39	    a[i] := i;
 40	    i := i + 1;
 41	  }
 42	  PrintArray(a);
 43	  var n := LinearSearch(a, 17);
 44	  print n, "\n";
 45	  var s : seq<int> := a[..];
 46	  print s, "\n";
 47	  s := a[2..16];
 48	  print s, "\n";
 49	  s := a[20..];
 50	  print s, "\n";
 51	  s := a[..8];
 52	  print s, "\n";
 53	
 54	  // Conversion to sequence should copy elements (sequences are immutable!)
 55	  a[0] := 42;
 56	  print s, "\n";
 57	
 58	  InitTests();
 59	
 60	  MultipleDimensions();
 61	
 62	  PrintArray<int>(null);
 63	}
 64	
 65	type lowercase = ch | 'a' <= ch <= 'z' witness 'd'
 66	
 67	method InitTests() {
 68	  var aa := new lowercase[3];
 69	  PrintArray(aa);
 70	  var s := "hello";
 71	  aa := new lowercase[|s|](i requires 0 <= i < |s| => s[i]);
 72	  PrintArray(aa);
 73	}
 74	
 75	method MultipleDimensions() {
 76	  var matrix := new int[2,8];
 77	  PrintMatrix(matrix);
 78	  matrix := DiagMatrix(3, 5, 0, 1);
 79	  PrintMatrix(matrix);
 80	
 81	  var cube := new int[3,0,4]((_,_,_) => 16);
 82	  print "cube dims: ", cube.Length0, " ", cube.Length1, " ", cube.Length2, "\n";
 83	
 84	//  FIXME: This breaks Java (and has for some time).
 85	//
 86	//  var jagged := new array<int>[5];
 87	//  var i := 0;
 88	//  while i < 5 {
 89	//    jagged[i] := new int[i];
 90	//    i := i + 1;
 91	//  }
 92	//  PrintArray(jagged);
 93	}
 94	
 95	method DiagMatrix<A>(rows: int, cols: int, zero: A, one: A)
 96	    returns (a: array2<A>)
 97	    requires rows >= 0
 98	{
 99	  return new A[rows, cols]((x,y) => if x==y then one else zero);
100	}
101	
102	method PrintMatrix<A>(m: array2<A>) {
103	  var i := 0;
104	  while i < m.Length0 {
105	    var j := 0;
106	    while j < m.Length1 {
107	      print m[i,j], " ";
108	      j := j + 1;
109	    }
110	    print "\n";
111	    i := i + 1;
112	  }
113	}
